package com.tripnest.config;
import com.tripnest.entity.*; import com.tripnest.repository.UserRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(UserRepository users,PasswordEncoder encoder,@Value("${app.seed.admin-email:}") String email,@Value("${app.seed.admin-password:}") String password){return args->{if(!email.isBlank()&&!password.isBlank()&&!users.existsByRole(Role.ADMIN)){User u=new User();u.setFullName("TripNest Admin");u.setEmail(email.trim().toLowerCase());u.setPasswordHash(encoder.encode(password));u.setRole(Role.ADMIN);users.save(u);}};} }
